examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchBreadcrumb(
        items = listOf(
            MonarchBreadcrumbItem({{parent}}),
            MonarchBreadcrumbItem({{title}}, linked = false),
        ),
        onItemClick = {},
    )
    Row(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchText(text = {{title}}, style = MonarchTextStyle.Title)
        MonarchBadge(text = {{status.label}}, tone = {{status.tone|tone}})
    }
    MonarchText(text = {{description}}, style = MonarchTextStyle.Body)
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchButton(text = {{actions.0.label}}, onClick = {}, variant = MonarchButtonVariant.Secondary)
        MonarchButton(text = {{actions.1.label}}, onClick = {}, variant = MonarchButtonVariant.Primary)
    }
}

