examples.setup:
val scrollBehavior = TopAppBarDefaults.exitUntilCollapsedScrollBehavior()
var menu by remember { mutableStateOf(false) }
var currentTab by remember { mutableIntStateOf(0) }

examples.code:
Scaffold(
    modifier = Modifier
        .height(MonarchTheme.spacing.space24 * 4)
        .nestedScroll(scrollBehavior.nestedScrollConnection),
    topBar = {
        LargeTopAppBar(
            title = { Text("Acme Ltd") },
            navigationIcon = {
                MonarchIconButton(label = "Back", onClick = {}) {
                    MonarchIcon(SampleIcons.ArrowBack, contentDescription = null)
                }
            },
            actions = {
                MonarchIconButton(label = "Add contact", onClick = {}) {
                    MonarchIcon(SampleIcons.Plus, contentDescription = null)
                }
                Box {
                    MonarchIconButton(label = "More actions", onClick = { menu = true }) {
                        MonarchIcon(SampleIcons.MoreVertical, contentDescription = null)
                    }
                    MonarchMenu(expanded = menu, onDismissRequest = { menu = false }) {
                        MonarchMenuItem(text = "Rename", onClick = { menu = false })
                        MonarchMenuItem(text = "Archive", onClick = { menu = false })
                    }
                }
            },
            scrollBehavior = scrollBehavior,
        )
    },
) { padding ->
    Column(Modifier.padding(padding)) {
        Row(
            modifier = Modifier.padding(horizontal = MonarchTheme.spacing.space4, vertical = MonarchTheme.spacing.space2),
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            MonarchBadge(text = "Active", tone = MonarchTone.Success)
            MonarchText(text = "Updated 5 minutes ago", style = MonarchTextStyle.Caption)
        }
        MonarchTabs(selectedIndex = currentTab, onSelectedIndexChange = { currentTab = it }) {
            tab("Overview")
            tab("Invoices")
        }
    }
}
